     .question-title {
       margin: 0 0 8px;
       font-size: 1.15rem;
       line-height: 1.45;
     }

     .help-text {
       margin: 0 0 18px;
       color: var(--muted);
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .choices {
       display: grid;
       gap: 12px;
     }

     .choice {
       position: relative;
     }

     .choice input {
       position: absolute;
       opacity: 0;
       inset: 0;
       cursor: pointer;
     }

     .choice label {
       display: flex;
       align-items: center;
       gap: 14px;
       padding: 16px 18px;
       border: 1px solid var(--border);
       border-radius: 16px;
       background: #fff;
       transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
       cursor: pointer;
     }

     .choice label::before {
       content: "";
       width: 22px;
       height: 22px;
       flex: 0 0 22px;
       border-radius: 7px;
       border: 1.5px solid rgba(79, 70, 229, 0.34);
       background: linear-gradient(180deg, #fff, #f8fafc);
       transition: all 0.18s ease;
     }

     .choice input:focus-visible + label,
     .choice label:hover {
       border-color: rgba(79, 70, 229, 0.42);
       box-shadow: 0 10px 24px rgba(79, 70, 229, 0.12);
       transform: translateY(-1px);
     }

     .choice input:checked + label {
       border-color: rgba(79, 70, 229, 0.56);
       background: linear-gradient(180deg, #fff, #f8faff);
       box-shadow: 0 14px 30px rgba(79, 70, 229, 0.12);
     }

     .choice input:checked + label::before {
       background: linear-gradient(135deg, var(--accent), #0ea5e9);
       border-color: transparent;
       box-shadow: inset 0 0 0 5px #fff;
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 16px;
       margin-top: 28px;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 15px 24px;
       font: inherit;
       font-weight: 700;
       color: #fff;
       background: linear-gradient(135deg, var(--accent), #0ea5e9);
       box-shadow: 0 18px 34px rgba(79, 70, 229, 0.28);
       cursor: pointer;
       transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 22px 40px rgba(79, 70, 229, 0.32);
       filter: saturate(1.05);
     }

     #result {
       min-height: 24px;
       color: var(--success);
       font-weight: 600;
     }

     @media (max-width: 640px) {
       .hero,
       form {
         padding: 24px;
       }

       .question-meta,
       .actions {
         flex-direction: column;
         align-items: flex-start;
       }

       button {
         width: 100%;
         justify-content: center;
       }
     }
   </style>
 </head>
